#include <stdio.h>

#define MAXV 10
#define MAXE 30

typedef struct { int u, v, w; } Edge;
Edge es[MAXE];
int parent[MAXV], rank_[MAXV];

int find(int x) {
    int r = x;
    while (parent[r] != r) r = parent[r];       /* 先找根 */
    while (parent[x] != r) {                    /* 第二趟：路径压缩 */
        int nxt = parent[x];
        parent[x] = r;
        x = nxt;
    }
    return r;
}

int unite(int a, int b) {
    int ra = find(a), rb = find(b);
    if (ra == rb) return 0;                     /* 已同集 => 成环 */
    if (rank_[ra] < rank_[rb]) parent[ra] = rb;
    else if (rank_[ra] > rank_[rb]) parent[rb] = ra;
    else { parent[rb] = ra; rank_[ra]++; }
    return 1;
}

int main(void) {
    int V = 5;
    int raw[][3] = {{0,1,4},{0,2,3},{1,2,1},{1,3,2},{2,3,4},{3,4,2},{2,4,5}};
    int E = 7;

    for (int i = 0; i < V; i++) { parent[i] = i; rank_[i] = 0; }
    for (int i = 0; i < E; i++) { es[i].u = raw[i][0]; es[i].v = raw[i][1]; es[i].w = raw[i][2]; }

    /* 按权升序冒泡排序（E 很小） */
    for (int i = 0; i < E - 1; i++)
        for (int j = 0; j < E - 1 - i; j++)
            if (es[j].w > es[j + 1].w) { Edge t = es[j]; es[j] = es[j + 1]; es[j + 1] = t; }

    printf("按权升序排序后：\n  ");
    for (int i = 0; i < E; i++) printf("(%d-%d,%d) ", es[i].u, es[i].v, es[i].w);
    printf("\n\n");

    int total = 0, cnt = 0;
    printf("Kruskal 选边过程：\n");
    for (int i = 0; i < E; i++) {
        int u = es[i].u, v = es[i].v, w = es[i].w;
        if (unite(u, v)) {
            printf("  选 (%d-%d, w=%d)  累计=%d\n", u, v, w, total + w);
            total += w;
            cnt++;   /* 不提前 break：走完全部边，把「被舍弃」的边也打印出来 */
        } else {
            printf("  跳 (%d-%d, w=%d)  %d 与 %d 已连通，加入会成环\n", u, v, w, u, v);
        }
    }

    printf("\n最小生成树：边数=%d（应为 V-1=%d），总权重=%d\n", cnt, V - 1, total);
    printf("\n要点：Kruskal 依据 cycle 性质 —— 成环时该边正是环上权最大者，必不属于某棵 MST。\n");
    printf("      总权重唯一，但树的形态不一定唯一（存在等权边时）。\n");
    return 0;
}
